using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{    
    [TestCategory("Coding-Rules")]
    [TestCategory("Basic")]
    [TestCategory("RJIT_CR_BC")]
    [TestCategory("RJIT_CR_BC_S")]
    [TestClass]
    public class RJIT_CR_BC_S_00003 : MsTestBase
    {
        /*
         * Code Rule RJIT_CR_BC_S_00003 emphasizes the importance of avoiding partial structs in production code.
         */
        [TestMethod]
        public void Do_Not_Use_Partial_Structs()
        {
            var result = (from @struct in Structs
                where @struct.SyntaxTree.DoesNotContain("partial Regex")
                from modifier in @struct.Modifiers
                where modifier == Modifier.Partial
                select new
                {
                    Error = $@"
Do not use partial classes in production code.
----------------------------------------------------------------------------------------------------------------------------
FullName:     {@struct.FullQualifiedName}
----------------------------------------------------------------------------------------------------------------------------
Struct name:   {@struct.SyntaxTree}
----------------------------------------------------------------------------------------------------------------------------
Should be:    {@struct.SyntaxTree.Replace(" partial", "").Replace("partial", "")}
----------------------------------------------------------------------------------------------------------------------------
"
                }).ToImmutableList();

            Assert.IsTrue(result.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_BC_S_00003

Do not use partial classes in production code. Found '{result.Count}':{Environment.NewLine}{result.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
}
